const methodAreas=[
{key:"communication",icon:"💬",title:["Общение и речь","Қарым-қатынас және сөйлеу","Communication and language"],goal:["Просить, выбирать, отказываться, сообщать о потребностях; понимать короткие фразы.","Сұрау, таңдау, бас тарту, қажеттілікті жеткізу; қысқа сөйлемдерді түсіну.","Request, choose, refuse, express needs and understand short phrases."],activities:[["Выбери из двух","Екі нұсқаның бірін таңда","Choose between two",["Положите перед ребёнком два знакомых предмета. Назовите каждый и покажите карточку. Примите взгляд, жест, слово или AAC-выбор.","Баланың алдына екі таныс зат қойыңыз. Әрқайсысын атап, карточканы көрсетіңіз. Көзқарасын, ишарасын, сөзін немесе AAC таңдауын қабылдаңыз.","Place two familiar objects in front of the child. Name each and model its symbol. Accept gaze, gesture, speech or AAC selection."]],["Скажи по-своему","Өз тәсіліңмен айт","Say it your way",["Во время любимой игры смоделируйте «ещё», «стоп», «помоги». Не требуйте повторения.","Сүйікті ойын кезінде «тағы», «тоқта», «көмектес» сөздерін үлгілеңіз. Қайталауды талап етпеңіз.","During a favourite game, model “more”, “stop”, “help”. Do not demand imitation."]]]},
{key:"thinking",icon:"🧩",title:["Мышление и внимание","Ойлау және зейін","Thinking and attention"],goal:["Сопоставлять, сортировать, замечать последовательности и решать небольшие задачи.","Сәйкестендіру, сұрыптау, реттілікті байқау және шағын тапсырмаларды шешу.","Match, sort, notice sequences and solve small problems."],activities:[["Найди такую же","Ұқсасын тап","Find the match",["Начните с двух одинаковых предметов или картинок. Затем найдите такую же среди двух вариантов.","Екі бірдей заттан немесе суреттен бастаңыз. Кейін екі нұсқаның ішінен ұқсасын табыңыз.","Start with identical objects or pictures, then find a match among two choices."]],["Что сначала?","Алдымен не?","What comes first?",["Разложите 2–3 фотографии знакомого действия, например мытья рук. Вместе восстановите порядок.","Таныс әрекеттің 2–3 суретін ретімен орналастырыңыз, мысалы қол жуу.","Arrange 2–3 pictures of a familiar routine, such as washing hands."]]]},
{key:"motor",icon:"🖐️",title:["Моторика","Қимыл-қозғалыс","Motor participation"],goal:["Участвовать руками в игре и бытовых действиях; двигательные цели согласовывать со специалистом.","Ойын мен күнделікті әрекеттерде қолды пайдалану; қимыл мақсаттарын маманмен келісу.","Use hands in play and daily tasks; agree movement goals with a specialist."],activities:[["Построй башню","Мұнара құрастыр","Build a tower",["Предложите крупные безопасные кубики. Пусть ребёнок кладёт, снимает или передаёт детали в своём темпе.","Қауіпсіз ірі текшелерді ұсыныңыз. Бала оларды өз қарқынымен қойсын, алсын немесе берсін.","Offer large safe blocks. Let the child stack, remove or pass pieces at their own pace."]],["Помоги в деле","Күнделікті іске көмектес","Help with a daily task",["Включите ребёнка в безопасное бытовое действие: положить салфетку или убрать лёгкую игрушку.","Баланы қауіпсіз іске қосыңыз: майлық қою немесе жеңіл ойыншықты жинау.","Invite the child into a safe daily task: place a napkin or put away a light toy."]]]},
{key:"daily",icon:"🌱",title:["Самостоятельность","Өзіндік дербестік","Independence"],goal:["Участвовать в повседневных последовательностях и постепенно выполнять доступные шаги самостоятельно.","Күнделікті әрекеттерге қатысу және қолжетімді қадамдарды біртіндеп өздігінен орындау.","Participate in daily routines and gradually do accessible steps independently."],activities:[["Моем руки","Қол жуамыз","Wash hands",["Используйте 3–4 картинки: открыть воду, намылить, смыть, вытереть. Помогайте по необходимости.","3–4 суретті қолданыңыз: суды ашу, сабындау, шаю, сүрту. Қажет болса көмектесіңіз.","Use 3–4 pictures: water on, soap, rinse, dry. Help only as needed."]],["Выбери одежду","Киімді таңда","Choose clothes",["Предложите два подходящих варианта одежды. Примите выбор взглядом, жестом, словом или карточкой.","Сәйкес екі киім нұсқасын ұсыныңыз. Көзқарас, ишара, сөз немесе карточка арқылы таңдауды қабылдаңыз.","Offer two suitable clothing options. Accept a choice by gaze, gesture, speech or card."]]]},
{key:"social",icon:"🤝",title:["Игра, общение и эмоции","Ойын, қарым-қатынас және эмоциялар","Play, social connection and feelings"],goal:["Совместное внимание, очередность, подражание, сюжетная игра и выражение чувств/границ.","Бірлескен зейін, кезектесу, еліктеу, рөлдік ойын және сезімдер мен шекараны білдіру.","Joint attention, turn-taking, imitation, pretend play and expressing feelings/boundaries."],activities:[["Моя очередь — твоя очередь","Менің кезегім — сенің кезегің","My turn — your turn",["Перекатывайте мяч или по очереди кладите кубики. Показывайте очередность словами и жестом.","Допты домалатыңыз немесе текшелерді кезекпен қойыңыз. Кезекті сөзбен және ишарамен көрсетіңіз.","Roll a ball or take turns placing blocks. Model turns with words and gestures."]],["Можно сказать «стоп»","«Тоқта» деуге болады","You can say “stop”",["В игре покажите карточки «стоп», «перерыв», «не хочу», «помоги». Уважайте отказ.","Ойында «тоқта», «үзіліс», «қаламаймын», «көмектес» карточкаларын көрсетіңіз. Бас тартуды құрметтеңіз.","Model “stop”, “break”, “no”, “help” cards during play. Respect every refusal."]]]},
{key:"literacy",icon:"🔤",title:["Чтение и математика","Оқу және математика","Literacy and numeracy"],goal:["Книги, значимые слова, буквы, количество и практические математические понятия.","Кітаптар, маңызды сөздер, әріптер, сандар және күнделікті математикалық ұғымдар.","Books, meaningful words, letters, quantities and practical maths."],activities:[["Читаем вместе","Бірге оқимыз","Read together",["Читайте короткую любимую книгу. Показывайте картинку и слово, делайте паузы, позволяйте указывать или выбирать.","Қысқа сүйікті кітапты оқыңыз. Сурет пен сөзді көрсетіп, үзіліс жасаңыз, баланың көрсетуіне мүмкіндік беріңіз.","Read a short favourite book. Point to pictures and words, pause, and let the child point or choose."]],["Считаем предметы","Заттарды санаймыз","Count real objects",["Считайте 1–3 реальные игрушки или фрукта. Сопоставляйте число с количеством, не торопите.","1–3 нақты ойыншықты немесе жемісті бірге санаңыз. Сан мен мөлшерді сәйкестендіріңіз.","Count 1–3 real toys or pieces of fruit. Match number to quantity without rushing."]]]}
];
