function renderMethod(){state.screen="method";const lang=state.lang;const langIndex={ru:0,kk:1,en:2}[lang]??0;const pick=values=>Array.isArray(values)?(values[langIndex]??values[0]??""):"";const statuses=store.get("method-status",{});const active=state.methodArea;const heading=lang==="kk"?"МОГУ даму жолы":lang==="en"?"MOGU development path":"Методика развития МОГУ";const cards=methodAreas.map((d,i)=>'<button class="method-domain" data-method-area="'+i+'"><span>'+d.icon+'</span><strong>'+pick(d.title)+'</strong><small>'+pick(d.goal)+'</small></button>').join("");const selected=Number.isInteger(active)?methodAreas[active]:null;const detail=selected?(()=>{const d=selected;return '<section class="method-detail"><div class="section-head"><h2>'+d.icon+' '+pick(d.title)+'</h2><button class="soft-button" data-action="method-close">×</button></div><p>'+pick(d.goal)+'</p>'+d.activities.map((a,j)=>{const id=d.key+"-"+j;const status=Math.max(0,Math.min(methodStatusLabels[lang].length-1,Number(statuses[id])||0));return '<article class="method-activity"><h3>'+pick(a.slice(0,3))+'</h3><p>'+pick(a[3])+'</p><div class="method-status"><span>'+methodStatusLabels[lang][status]+'</span><div>'+methodStatusLabels[lang].map((label,k)=>'<button class="'+(status===k?"selected":"")+'" data-method-status="'+id+'" data-value="'+k+'" aria-label="'+label+'">'+(k+1)+'</button>').join("")+'</div></div></article>'}).join("")+'</section>'})():"";$("#app-main").innerHTML=head(heading,methodIntro[lang])+'<div class="method-note">🌱 '+methodIntro[lang]+'</div><div class="method-domain-grid">'+cards+'</div>'+detail+'<div class="method-footnote">Важно: двигательные, пищевые и речевые терапевтические упражнения подбираются профильным специалистом. МОГУ дополняет занятия, но не заменяет их.</div>';nav("adult")}
