function guideMessage(){const set=guideLines[state.lang]||guideLines.ru;if(state.screen==="adventures"&&Number.isInteger(state.adventureTrack)){const w=adventureTracks[state.adventureTrack],m=w&&w.missions[state.adventureMission||0],i=state.lang==="kk"?1:state.lang==="en"?2:0;if(m)return m[2][i]+". "+m[3][i]}return set[state.screen]||set.home}
function announceGuide(message=guideMessage()){speakMadina(message,state.lang)}

let toastTimer;function toast(s){const el=$("#toast");el.textContent=s;el.classList.add("visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove("visible"),2300)}
function head(title,sub){return '<div class="screen-top"><button class="back-button" data-action="home">'+t("back")+'</button><div class="screen-heading-copy"><h1 class="screen-title">'+title+'</h1><p class="screen-subtitle">'+(sub||"")+'</p></div><button class="page-guide" data-action="guide-speak" aria-label="Послушать Мадину"><img src="./assets/madina-guide.webp" alt=""><span><strong>'+(state.lang==="kk"?"Мадина":state.lang==="en"?"Madina":"Мадина")+'</strong><small>'+(state.lang==="kk"?"Тыңдау":"Послушать")+' 🔊</small></span></button></div>'}
let activeMadinaAudio=null;
let madinaSpeechRun=0;
const MADINA_API_BASE="https://mogu-web-production.up.railway.app";
let madinaAudioManifest={entries:{}};
const madinaAudioManifestReady=fetch(MADINA_API_BASE+"/api/madina/library/manifest.json",{cache:"no-cache"})
 .then(response=>response.ok?response.json():null)
 .then(data=>{if(data&&data.voiceId==="33d2eff7a2f449b4b1a2e95d42ebbb33")madinaAudioManifest=data;})
 .catch(()=>{});
function findMadinaLibraryAudio(text,language){
 const entries=Object.values(madinaAudioManifest.entries||{});
 const entry=entries.find(item=>item.lang===language&&item.text===text);
 return entry?MADINA_API_BASE+"/api/madina/library/"+(entry.src.startsWith("./")?entry.src.slice(2):entry.src):null;
}
function cancelMadinaSpeech(){madinaSpeechRun++;if(activeMadinaAudio){const old=activeMadinaAudio;activeMadinaAudio=null;old.onended=null;old.onerror=null;try{const src=old.src;if(src&&src.startsWith("blob:"))URL.revokeObjectURL(src);old.pause();old.removeAttribute("src");old.load()}catch(_){}}if("speechSynthesis"in window)speechSynthesis.cancel();const el=document.querySelector(".madina-character");if(el)el.classList.remove("is-speaking")}
function speakMadina(text,language=state.lang,onComplete=null,rateOverride=null){
 const run=++madinaSpeechRun;
 let completed=false;
 const complete=()=>{if(completed||run!==madinaSpeechRun)return;completed=true;if(typeof onComplete==="function")onComplete()};
 const cleanupAudio=()=>{if(activeMadinaAudio){const old=activeMadinaAudio;activeMadinaAudio=null;old.onended=null;old.onerror=null;try{const src=old.src;if(src&&src.startsWith("blob:"))URL.revokeObjectURL(src);old.pause();old.removeAttribute("src");old.load()}catch(_){}}};
 const spokenText=String(text??"").replace(/\p{Extended_Pictographic}/gu,"").replace(/[\uFE0E\uFE0F\u200D\u{1F1E6}-\u{1F1FF}]/gu,"").replace(/[\\\/"'«»“”‘’„‟]/g,"").replace(/\s+/g," ").replace(/\s+([,.!?])/g,"$1").trim();
 if(!spokenText){complete();return false}
 cleanupAudio();
 if("speechSynthesis"in window)speechSynthesis.cancel();
 const playCloud=async()=>{
  try{
   await madinaAudioManifestReady;
   if(run!==madinaSpeechRun)return;
   const libraryUrl=findMadinaLibraryAudio(spokenText,language);
   let audio;
   if(libraryUrl){
    audio=new Audio(libraryUrl);
   }else{
    const response=await fetch(MADINA_API_BASE+"/api/madina/speech",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({text:spokenText,language:language}),signal:AbortSignal.timeout(35000)});
    if(!response.ok)throw new Error("TTS "+response.status);
    const blob=await response.blob();
    if(!blob.size||run!==madinaSpeechRun)throw new Error("Empty or cancelled audio");
    audio=new Audio(URL.createObjectURL(blob));
   }
   activeMadinaAudio=audio;
   audio.volume=Math.max(0,Math.min(1,Number(audioPrefs.voiceVolume??.95)));
   audio.onended=()=>{if(run!==madinaSpeechRun)return;activeMadinaAudio=null;if(audio.src.startsWith("blob:"))URL.revokeObjectURL(audio.src);const el=document.querySelector(".madina-character");if(el)el.classList.remove("is-speaking");complete()};
   audio.onerror=()=>{if(run!==madinaSpeechRun)return;activeMadinaAudio=null;URL.revokeObjectURL(audio.src);const el=document.querySelector(".madina-character");if(el)el.classList.remove("is-speaking");toast(language==="kk"?"Мадинаның дауысын жүктеу мүмкін болмады. Интернетті тексер.":language==="en"?"Madina's voice could not be loaded. Check your connection.":"Не удалось загрузить детский голос Мадины. Проверь интернет.");complete()};
   const el=document.querySelector(".madina-character");if(el)el.classList.add("is-speaking");
   await audio.play();
  }catch(_){
   if(run!==madinaSpeechRun)return;
   cleanupAudio();
   const el=document.querySelector(".madina-character");if(el)el.classList.remove("is-speaking");
   toast(language==="kk"?"Мадинаның дауысын жүктеу мүмкін болмады. Интернетті тексер.":language==="en"?"Madina's voice could not be loaded. Check your connection.":"Не удалось загрузить детский голос Мадины. Проверь интернет.");
   complete();
  }
 };
 playCloud();
 return true;
}
function speakWelcome(retry=false){if(state.welcomeAudioStarted||(state.welcomeSpoken&&!retry))return;state.welcomeSpoken=true;const phrase=state.lang==="kk"?"Сәлем! Менің атым Мадина, бірге ойнайық!":state.lang==="en"?"Hello! My name is Madina. Let’s play together!":"Привет! Меня зовут Мадина, давай поиграем!";speakMadina(phrase)}
