const adventureLabels={ru:{title:"Приключения МОГУ",sub:"Выбирай мир, знакомься с героями и открывай новое. Здесь можно пробовать снова и идти в своём темпе.",start:"Начать приключение",back:"К мирам",done:"Ты открыл это задание!",retry:"Попробуем ещё раз?",bridge:"Попробуй в настоящей жизни",stars:"Открытия",missions:"заданий",allDone:"Все задания этого мира пройдены. Можно играть снова!",buddy:"Мадина приготовила для тебя игру!",complete:"Я попробовал!",choose:"Выбери ответ",note:"Взрослый может подсказать, показать карточку или дать время. Любой способ ответа подходит."},kk:{title:"МОГУ оқиғалары",sub:"Әлемді таңда, кейіпкерлермен таныс және жаңалық аш. Қайта байқап көруге болады.",start:"Оқиғаны бастау",back:"Әлемдерге оралу",done:"Бұл тапсырманы аштың!",retry:"Қайта байқап көрейік пе?",bridge:"Өмірде бірге жасап көр",stars:"Жаңалықтар",missions:"тапсырма",allDone:"Бұл әлемнің тапсырмалары аяқталды. Қайта ойнауға болады!",buddy:"Мадина саған ойын дайындады!",complete:"Мен байқап көрдім!",choose:"Жауапты таңда",note:"Ересек адам көмектесіп, суретті көрсете немесе күтуге мүмкіндік бере алады. Кез келген жауап тәсілі жарайды."},en:{title:"MOGU Adventures",sub:"Choose a world, meet the characters and discover something new. You can try again and go at your own pace.",start:"Start adventure",back:"Back to worlds",done:"You discovered this activity!",retry:"Shall we try again?",bridge:"Try it in real life",stars:"Discoveries",missions:"missions",allDone:"You explored every mission in this world. You can play again!",buddy:"Madina has a game for you!",complete:"I tried it!",choose:"Choose an answer",note:"An adult can help, model a symbol or give more time. Any way of answering is welcome."}};
function renderAdventures(){state.screen="adventures";const l=state.lang,L=adventureLabels[l],progress=store.get("adventure-done",[]),active=state.adventureTrack;const total=adventureTracks.reduce((n,x)=>n+x.missions.length,0);$("#app-main").innerHTML=head(L.title,L.sub)+'<div class="adventure-hero"><img src="./assets/madina-guide.webp" alt="Мадина"><div><strong>'+L.buddy+'</strong><p>'+L.sub+'</p><span>⭐ '+progress.length+' / '+total+' '+L.stars+'</span></div></div>'+(active===undefined||active===null?'<div class="adventure-worlds">'+adventureTracks.map((w,i)=>{const done=w.missions.filter(m=>progress.includes(w.key+":"+m[0])).length;return '<button class="adventure-world" data-adventure="'+i+'"><span class="adventure-icon">'+w.icon+'</span><strong>'+w.name[l==="kk"?1:l==="en"?2:0]+'</strong><small>'+w.about[l==="kk"?1:l==="en"?2:0]+'</small><span class="adventure-meter">'+done+' / '+w.missions.length+' ⭐</span></button>'}).join("")+'</div>':'');if(active!==undefined&&active!==null){const w=adventureTracks[active];const mi=state.adventureMission||0;const m=w.missions[mi];const id=w.key+":"+m[0];const done=progress.includes(id);$("#app-main").innerHTML+= '<section class="adventure-play"><button class="soft-button" data-action="adventure-back">← '+L.back+'</button><div class="adventure-progress">'+w.icon+' '+w.name[l==="kk"?1:l==="en"?2:0]+' · '+(mi+1)+' / '+w.missions.length+'</div><div class="adventure-mascot">✨</div><h2>'+m[2][l==="kk"?1:l==="en"?2:0]+'</h2><p class="adventure-question">'+m[3][l==="kk"?1:l==="en"?2:0]+'</p><div class="adventure-options">'+m[4].map((o,i)=>'<button class="adventure-option" data-mission-answer="'+i+'"><strong>'+o[l==="kk"?1:l==="en"?2:0]+'</strong></button>').join("")+'</div><p class="adventure-feedback" aria-live="polite">'+(done?L.done:state.adventureFeedback||L.note)+'</p><div class="adventure-bridge"><strong>'+L.bridge+'</strong><p>'+m[6][l==="kk"?1:l==="en"?2:0]+'</p></div>'+(done?'<button class="adventure-next" data-action="adventure-next">'+(mi===w.missions.length-1?L.back:L.start+' →')+'</button>':(state.adventureAnswered?'<button class="adventure-next" data-action="adventure-complete">'+L.complete+'</button>':''))+'<p class="adventure-note">'+L.note+'</p></section>'}}
function selectAdventure(i){if(!Number.isInteger(i)||!adventureTracks[i])return;state.adventureTrack=i;state.adventureMission=0;state.adventureAnswered=false;state.adventureFeedback="";renderAdventures()}
