function shuffleLessonDeck(deck){for(let i=deck.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]]}return deck}
const lessonFeedbackPhrases={
 great:{
  ru:["Умница! Отлично получилось!","Как здорово! Ты справился!","Правильно! Я тобой горжусь!","Вот это да! У тебя получилось!","Молодец! Так держать!"],
  kk:["Жарайсың! Өте жақсы!","Керемет! Сен орындадың!","Дұрыс! Мен сені мақтан тұтамын!","Тамаша! Қолыңнан келді!","Өте жақсы! Осылай жалғастыр!"],
  en:["Brilliant! You did it!","Wonderful! You got it right!","Correct! I'm proud of you!","Amazing work! You did it!","Well done! Keep it up!"]
 },
 try:{
  ru:["Ничего страшного! Попробуй ещё раз.","Почти получилось! Давай ещё раз.","Ошибаться не страшно. У тебя получится!","Давай подумаем вместе и попробуем снова.","Не торопись. Попробуй ещё раз!"],
  kk:["Ештеңе етпейді! Қайта байқап көр.","Аз қалды! Тағы бір рет көрейік.","Қателесу қорқынышты емес. Сенің қолыңнан келеді!","Бірге ойланып, қайта байқап көрейік.","Асықпа. Тағы бір рет байқап көр!"],
  en:["That's okay! Let's try again.","So close! Give it another try.","It's okay to make mistakes. You can do it!","Let's think together and try once more.","Take your time. Try again!"]
 }
};
let lastLessonFeedbackIndex={great:-1,try:-1};
function chooseLessonFeedback(kind,lang){
 const list=lessonFeedbackPhrases[kind][lang]||lessonFeedbackPhrases[kind].ru;
 let index=Math.floor(Math.random()*list.length);
 if(list.length>1&&index===lastLessonFeedbackIndex[kind])index=(index+1+Math.floor(Math.random()*(list.length-1)))%list.length;
 lastLessonFeedbackIndex[kind]=index;
 return list[index];
}

let lessonSpeechRun=0;
function lessonPromptText(){if(!state.lesson)return "";const l=state.lang,question=state.lesson.question[l]||state.lesson.question.ru;const choices=state.lesson.options.map(x=>t(x[0])).join(", ");const prefix=l==="kk"?"Жауап нұсқалары: ":l==="en"?"Answer choices: ":"Варианты ответа: ";return question+". "+prefix+choices+"."}
function speakLessonPrompt(){
 if(!state.lesson)return;
 const run=++lessonSpeechRun,l=state.lang,question=state.lesson.question[l]||state.lesson.question.ru;
 if(activeLesson==="thinking"||activeLesson==="language"){speakMadina(question,l);return;}
 const choices=state.lesson.options.map(x=>t(x[0])).join(", ");
 const prefix=l==="kk"?"Жауап нұсқалары: ":l==="en"?"Answer choices: ":"Варианты ответа: ";
 const later=(fn,delay)=>setTimeout(()=>{if(run===lessonSpeechRun&&state.screen==="learn"&&state.lessonMode)fn()},delay);
 if(activeLesson==="reading"){
  const match=question.match(l==="en"?/^Find the letter\\s+(.+)[.!?]?$/i:l==="kk"?/^(.+?) әрпін тап[.!?]?$/i:/^Найди букву\\s+(.+)[.!?]?$/i);
  if(match){
   const instruction=l==="en"?"Find the letter":l==="kk"?"Әріпті тап":"Найди букву";
   speakMadina(instruction,l,()=>later(()=>speakMadina(match[1],l,()=>later(()=>speakMadina(prefix+choices,l,null,.65),120),.65),120),.65);
  }else{
   speakMadina(question,l,()=>later(()=>speakMadina(prefix+choices,l,null,.72),100),.72);
  }
  return;
 }
 speakMadina(lessonPromptText(),l);
}
function newLesson(){
 const set=lessonSets[activeLesson]||lessonSets.colors;
 let item,colorPosition=null,colorTotal=null;
 if(activeLesson==="colors"||activeLesson==="math"||activeLesson==="reading"||activeLesson==="thinking"||activeLesson==="language"){
  const isMath=activeLesson==="math",isReading=activeLesson==="reading",isThinking=activeLesson==="thinking",isLanguage=activeLesson==="language";
  let deck=isMath?mathLessonDeck:isReading?readingLessonDeck:isThinking?thinkingLessonDeck:isLanguage?languageLessonDeck:colorLessonDeck;
  const lastIndex=isMath?lastMathQuestionIndex:isReading?lastReadingQuestionIndex:isThinking?lastThinkingQuestionIndex:isLanguage?lastLanguageQuestionIndex:lastColorQuestionIndex;
  if(!deck.length){
   deck=shuffleLessonDeck(Array.from({length:set.length},(_,i)=>i));
   if(isMath){mathLessonDeck=deck;mathLessonPosition=0}else if(isReading){readingLessonDeck=deck;readingLessonPosition=0}else if(isThinking){thinkingLessonDeck=deck;thinkingLessonPosition=0}else if(isLanguage){languageLessonDeck=deck;languageLessonPosition=0}else{colorLessonDeck=deck;colorLessonPosition=0}
   if(set.length>1&&deck[deck.length-1]===lastIndex){
    const swapIndex=Math.floor(Math.random()*(deck.length-1));
    [deck[swapIndex],deck[deck.length-1]]=[deck[deck.length-1],deck[swapIndex]];
   }
  }
  const questionIndex=deck.pop();
  item=set[questionIndex];
  if(isMath){lastMathQuestionIndex=questionIndex;colorPosition=++mathLessonPosition}
  else if(isReading){lastReadingQuestionIndex=questionIndex;colorPosition=++readingLessonPosition}
  else if(isThinking){lastThinkingQuestionIndex=questionIndex;colorPosition=++thinkingLessonPosition}
  else{lastColorQuestionIndex=questionIndex;colorPosition=++colorLessonPosition}
  colorTotal=set.length;
 }else item=set[Math.floor(Math.random()*set.length)];
 const options=shuffleLessonDeck(item.options.slice());
 state.lesson={topic:activeLesson,question:item.question,options,answer:item.answer,colorPosition,colorTotal,lastAnswer:null,lastCorrect:false,feedback:""};
}
function renderWorld(){state.screen="world";const groups=["animals","food","home","clothes","transport","nature"];$("#app-main").innerHTML=head(t("world"),t("worldDesc"))+'<div class="section-head"><h2>'+t("explore")+'</h2><span class="hint">🌱</span></div><div class="world-grid">'+worldData.map(x=>'<button class="world-card" data-world="'+x[0]+'" data-icon="'+x[1]+'"><span class="pic">'+x[1]+'</span><strong>'+t(x[0])+'</strong><small>'+t(x[2])+'</small></button>').join("")+'</div>'+(state.worldItem?'<div class="detail-card"><span class="detail-pic">'+state.worldItem.icon+'</span><div><h3>'+t(state.worldItem.key)+'</h3><p>'+t("explore")+'</p></div><button class="soft-button" data-action="worldsay">🔊</button></div>':"");nav("home")}
