function renderAdult(){state.screen="adult";const s=state.settings,kk=state.lang==="kk",en=state.lang==="en";const title=kk?"Баптаулар":en?"Settings":"Настройки";const parent=kk?"Ата-аналарға":en?"For parents":"Родителям";const sound=kk?"Дыбыс":en?"Sound":"Звук";const parentBody='<section class="parent-panel"><div class="parent-welcome"><strong>'+parent+'</strong><p>'+(kk?"Бұл бөлім ересектерге арналған.":en?"This section is for adults and caregivers.":"Этот раздел предназначен для взрослых и родителей.")+'</p></div><button class="method-entry" data-action="method">🌱 <span class="method-title">'+(kk?"МОГУ даму әдістемесі":en?"MOGU development guide":"Методика развития МОГУ")+'</span> →</button><div class="adult-grid"><section class="setting-card"><h3>'+t("size")+'</h3><div class="setting-control">'+["normal","large","xlarge"].map(v=>'<button class="'+(s.size===v?"selected":"")+'" data-setting="size" data-value="'+v+'">'+t(v)+'</button>').join("")+'</div></section><section class="setting-card"><h3>'+t("simple")+'</h3><div class="setting-control"><button class="'+(!s.simple?"selected":"")+'" data-setting="simple" data-value="false">'+t("off")+'</button><button class="'+(s.simple?"selected":"")+'" data-setting="simple" data-value="true">'+t("on")+'</button></div></section><section class="setting-card"><h3>'+t("motion")+'</h3><div class="setting-control"><button class="'+(s.motion?"selected":"")+'" data-setting="motion" data-value="true">'+t("on")+'</button><button class="'+(!s.motion?"selected":"")+'" data-setting="motion" data-value="false">'+t("off")+'</button></div></section><section class="setting-card"><h3>'+t("rate")+'</h3><div class="setting-control"><button data-setting="rate" data-value="0.7">Медленно</button><button data-setting="rate" data-value="0.85">Обычно</button><button data-setting="rate" data-value="1">Быстрее</button></div></section></div><div class="privacy-note">🔒 '+t("privacy")+'</div></section>';$("#app-main").innerHTML='<div class="settings-page"><div class="settings-heading"><h1>'+title+'</h1><button class="soft-button" data-action="home">← '+t("back")+'</button></div><div class="settings-tabs"><button class="'+(state.settingsTab==="sound"?"active":"")+'" data-settings-tab="sound">🔊 '+sound+'</button><button class="'+(state.settingsTab==="parents"?"active":"")+'" data-settings-tab="parents">👨‍👩‍👧 '+parent+'</button></div>'+(state.settingsTab==="sound"?soundPanel():parentBody)+'</div>';document.getElementById("bottom-nav").hidden=false;nav("home")}
