if(b.dataset.adventure!==undefined){selectAdventure(Number(b.dataset.adventure));announceGuide();return}if(b.dataset.missionAnswer!==undefined){const w=adventureTracks[state.adventureTrack],m=w&&w.missions[state.adventureMission],choice=Number(b.dataset.missionAnswer),l=state.lang;if(!m||!Number.isInteger(choice)||choice<0||choice>=m[4].length)return;state.adventureAnswered=choice===m[5];state.adventureFeedback=state.adventureAnswered?(l==="kk"?"Жарайсың! Дұрыс!":l==="en"?"Great discovery!":"У тебя получилось! Отличное открытие!"):(l==="kk"?"Қайта байқап көр. Асықпа!":l==="en"?"Try another choice. Take your time!":"Попробуй ещё раз. Не спеши!");renderAdventures();return}if(b.dataset.methodArea!==undefined){state.methodArea=Number(b.dataset.methodArea);renderMethod();return}if(b.dataset.methodStatus){const statuses=store.get("method-status",{});statuses[b.dataset.methodStatus]=Number(b.dataset.value);store.set("method-status",statuses);renderMethod();return}if(b.dataset.action){const a=b.dataset.action;if(a==="home"){state.screen="home";render();announceGuide()}if(a==="settings"){state.settingsTab="sound";state.screen="adult";render();announceGuide()}if(a==="start"){state.screen="home";render();announceGuide()}if(a==="welcome-voice"){speakMadina(state.lang==="kk"?"Сәлем! Менің атым Мадина, бірге ойнайық!":state.lang==="en"?"Hello! My name is Madina. Let’s play together!":"Привет! Меня зовут Мадина, давай поиграем!");return}if(a==="guide-speak"){announceGuide();return}if(a==="voice-test"){speakMadina(state.lang==="kk"?"Сәлем! Мен Мадинамын! Кәне, бірге ойнайық!":state.lang==="en"?"Hi! I am Madina! Let’s play together!":"Привет! Я Мадина! Давай поиграем вместе!");return}if(a==="adventure-back"){state.adventureTrack=null;state.adventureMission=0;state.adventureAnswered=false;renderAdventures()}if(a==="adventure-complete"){if(!state.adventureAnswered){toast(state.lang==="kk"?"Алдымен жауапты таңда":state.lang==="en"?"Choose an answer first":"Сначала выбери ответ");return}const w=adventureTracks[state.adventureTrack],m=w.missions[state.adventureMission],id=w.key+":"+m[0],done=store.get("adventure-done",[]);if(!done.includes(id)){done.push(id);store.set("adventure-done",done)}state.adventureFeedback="";renderAdventures()}if(a==="adventure-next"){const w=adventureTracks[state.adventureTrack];if(state.adventureMission<w.missions.length-1){state.adventureMission++;state.adventureAnswered=false;state.adventureFeedback="";renderAdventures()}else{state.adventureTrack=null;state.adventureMission=0;state.adventureAnswered=false;renderAdventures()}}if(a==="method"){state.methodArea=null;renderMethod()}if(a==="method-close"){state.methodArea=null;renderMethod()}if(a==="undo"){state.phrase=state.history.pop()||[];renderTalk()}if(a==="remove"){if(state.phrase.length){state.history.push(state.phrase.slice());state.phrase.pop()}renderTalk()}if(a==="clear"){state.history.push(state.phrase.slice());state.phrase=[];renderTalk()}if(a==="say"){if(!state.phrase.length){toast(t("speakFirst"));return}const phrase=state.phrase.map(x=>t(x.key)).join(", ");speak(phrase);state.stats.spoken++;saveStats()}if(a==="repeat"&&state.lesson){speakLessonPrompt();return}if(a==="newlesson"){newLesson();renderLearn();speakLessonPrompt()}if(a==="learn-back"){state.lessonMode=false;lessonSpeechRun++;cancelMadinaSpeech();renderLearn()}if(a==="worldsay"&&state.worldItem)speak(t(state.worldItem.key));if(a==="feelsay"&&state.feeling)speak(t("iFeel")+" "+t(state.feeling.key));if(a==="feeladd"&&state.feeling){addPhrase(state.feeling.key,state.feeling.icon);state.screen="talk"}return}
